(function(s){const catalogue={"BASIS-API-001":{"what":"No `Authorization: Bearer` header.","fix":"Send a Firebase ID token.","retry":"yes","signal":null},"BASIS-API-002":{"what":"The header is not `Bearer <token>`.","fix":"Fix the header format.","retry":"yes","signal":null},"BASIS-API-003":{"what":"The ID token has expired.","fix":"Refresh the token and repeat.","retry":"yes","signal":null},"BASIS-API-004":{"what":"The ID token was revoked (production checks revocation).","fix":"Sign in again.","retry":"yes","signal":null},"BASIS-API-005":{"what":"The Firebase user is disabled.","fix":"An administrator must re-enable the account.","retry":"no","signal":null},"BASIS-API-006":{"what":"The Firebase user was deleted; the token is still signed.","fix":"Create or restore the account.","retry":"no","signal":null},"BASIS-API-007":{"what":"The token does not verify (wrong project, tampered, not an ID token).","fix":"Send a token for this project.","retry":"yes","signal":null},"BASIS-API-008":{"what":"The token verified but carries no `uid`/`sub` claim.","fix":"Report to the operator: the identity provider's claims changed.","retry":"no","signal":null},"BASIS-API-009":{"what":"Google's public signing keys could not be fetched.","fix":"Retry; check the server's egress to Google if it persists.","retry":"yes","signal":null},"BASIS-API-010":{"what":"The caller's role in the study's or firm's organization is too low (viewer < engineer < owner).","fix":"Ask an owner to raise the role, or have someone with the role act.","retry":"no","signal":null},"BASIS-API-011":{"what":"The row does not exist or is not visible to the caller (the two are indistinguishable on purpose).","fix":"Check the id; check the caller is a member of the study's firm.","retry":"no","signal":null},"BASIS-API-012":{"what":"A repository conflict with no more specific type.","fix":"Read the current state and repeat with it.","retry":"yes","signal":null},"BASIS-API-013":{"what":"The request did not validate: a field is missing, out of range, the wrong type, or (intake) violates a rule such as a non-capitalizable cost category.","fix":"Fix the fields named in `errors`.","retry":"yes","signal":null},"BASIS-API-014":{"what":"Unprocessable with no more specific type.","fix":"Read `detail`.","retry":"no","signal":null},"BASIS-API-015":{"what":"Bad request with no more specific type.","fix":"Read `detail`.","retry":"no","signal":null},"BASIS-API-016":{"what":"The JSON body is larger than 1 MiB.","fix":"Files never go to the API: request a signed URL and upload there.","retry":"no","signal":null},"BASIS-API-017":{"what":"The caller exceeded the per-user limit (240 reads or 60 mutations per minute by default).","fix":"Wait `Retry-After` seconds.","retry":"yes","signal":null},"BASIS-API-018":{"what":"Every pooled database connection was busy for `pool_timeout`.","fix":"Retry; if it persists the API is under-provisioned (docs/perf/LOAD_TESTING.md).","retry":"yes","signal":null},"BASIS-API-019":{"what":"A new database connection could not be opened (server down, network, \"cannot accept connections now\").","fix":"Retry; check Cloud SQL and the connector.","retry":"yes","signal":null},"BASIS-API-020":{"what":"The API started with neither `DATABASE_URL` nor `CLOUD_SQL_INSTANCE`.","fix":"Configure the database and restart the API.","retry":"no","signal":null},"BASIS-API-021":{"what":"`TEMPORAL_ADDRESS` is empty: the API has no workflow service.","fix":"Configure Temporal and restart the API.","retry":"no","signal":null},"BASIS-API-022":{"what":"Temporal did not answer within the call timeout or refused the connection.","fix":"Retry; a start that got this far already moved the study to `extracting`, and the repeat converges.","retry":"yes","signal":null},"BASIS-API-023":{"what":"A dependency is unavailable with no more specific code.","fix":"Retry after `Retry-After`.","retry":"yes","signal":null},"BASIS-API-024":{"what":"An unexpected exception escaped a route; the stack trace is in the API log under the request id.","fix":"Search the API logs for the `request_id`; file the defect.","retry":"yes","signal":null},"BASIS-API-025":{"what":"A plain HTTP error: an unknown path (404) or a method the path does not serve (405, with `Allow`).","fix":"Check the path and method against docs/api/openapi.json.","retry":"no","signal":null},"BASIS-API-026":{"what":"No `Idempotency-Key` header.","fix":"Send a fresh key (a UUID) per request.","retry":"yes","signal":null},"BASIS-API-027":{"what":"The key has a character outside the documented class or is too long.","fix":"Use visible ASCII (a UUID).","retry":"yes","signal":null},"BASIS-API-028":{"what":"The key was used within 24 hours for a different route or body.","fix":"Use a new key for a new request.","retry":"yes","signal":null},"BASIS-API-029":{"what":"The first request with this key is still running.","fix":"Wait for it, then repeat with the same key to get its stored answer.","retry":"yes","signal":null},"BASIS-API-030":{"what":"The `cursor` does not decode (it is an opaque token the server issued).","fix":"Pass a `next_cursor` from the previous page unchanged.","retry":"yes","signal":null},"BASIS-API-031":{"what":"The caller is not a member of that firm (firms are not enumerable).","fix":"Check `GET /v1/me` for the caller's firms.","retry":"no","signal":null},"BASIS-API-040":{"what":"The `fingerprint` sent is not the current one: the intake, the cost index store, the square-foot model or a pricing setting changed since the preview.","fix":"Preview again (`GET .../assets/reprice`), review the new impact, send its fingerprint.","retry":"yes","signal":null},"BASIS-API-041":{"what":"The intake's property use changed since the assets were classified (27.5- or 39-year building, the rules table's class): carrying the classifications would be wrong.","fix":"Reject the assets review so the assets are classified again.","retry":"no","signal":null},"BASIS-API-042":{"what":"The study is not waiting at the assets review of that revision.","fix":"Wait for the assets review to open, or use the current revision.","retry":"yes","signal":null},"BASIS-API-043":{"what":"The signed-in account is not a platform operator (its uid is not in `OPS_OPERATOR_UIDS`); a firm role never grants it.","fix":"An operator with deployment access adds the uid to `OPS_OPERATOR_UIDS`.","retry":"no","signal":null},"BASIS-API-044":{"what":"The Postgres-backed rate limiter (`RATE_LIMIT_STORE=postgres`, the default in staging and prod) could not reach the database; the request was counted against a per-process budget instead, so the published limit holds per API instance until the database is back.","fix":"Restore the database (the same cause makes every `/v1` route answer 503 `BASIS-API-0xx`); nothing to reset, the shared log resumes on the next request.","retry":"yes","signal":null},"BASIS-API-045":{"what":"A batch of browser error events is larger than `MAX_BATCH_BYTES` (256 KiB), the route's own cap under the API's 1 MiB body limit; the batch was not read.","fix":"The web app's capture module caps each event (stack 16,000 characters, 50 breadcrumbs) and sends at most 20 per batch, so this means a client outside it; send smaller batches.","retry":"no","signal":null},"BASIS-API-046":{"what":"This host has no evaluation run records to list: `BASIS_EVAL_DATA_DIR` is unset (the default on every deployed host), names a directory that does not exist, or the evaluation tooling (`evals`) is not installed in this image. The answer is explicit so that it is never read as \"no runs\".","fix":"Run the API where the evaluation data lives, with `BASIS_EVAL_DATA_DIR` set; the data never enters a deployment.","retry":"no","signal":null},"BASIS-API-047":{"what":"The run file (a console log, a ledger) is larger than the route serves (`MAX_FILE_BYTES`, 8 MiB): the file is redacted in memory before it is sent, so the size is bounded.","fix":"Read the file from the run directory on the host.","retry":"no","signal":null},"BASIS-FIRM-001":{"what":"The caller belongs to no firm: firms are invite-only.","fix":"Accept an invitation (`GET /v1/me` lists the ones waiting for the verified email).","retry":"no","signal":null},"BASIS-FIRM-002":{"what":"The caller may create studies in several firms and gave no `org_id`.","fix":"Set `org_id`.","retry":"yes","signal":null},"BASIS-FIRM-003":{"what":"The token does not assert a verified email, which an invitation is bound to and a firm's first owner must have.","fix":"Verify the email with the identity provider, sign in again.","retry":"no","signal":null},"BASIS-FIRM-004":{"what":"The change would leave the firm without an owner.","fix":"Make another member owner first.","retry":"no","signal":null},"BASIS-FIRM-005":{"what":"The email already belongs to a member of the firm.","fix":"Nothing to do; change their role instead.","retry":"no","signal":null},"BASIS-FIRM-006":{"what":"The firm already has an open invitation for this email.","fix":"Revoke it first, or wait for the answer.","retry":"no","signal":null},"BASIS-FIRM-007":{"what":"The invitation was already accepted.","fix":"Nothing to do.","retry":"no","signal":null},"BASIS-FIRM-008":{"what":"The invitation was declined.","fix":"Invite again.","retry":"no","signal":null},"BASIS-FIRM-009":{"what":"The invitation was revoked.","fix":"Ask for a new invitation.","retry":"no","signal":null},"BASIS-FIRM-010":{"what":"The invitation expired.","fix":"Ask for a new invitation.","retry":"no","signal":null},"BASIS-FIRM-011":{"what":"Firms are set up by Basis (`FIRM_SELF_SERVE` off, the default): a signed-in user cannot create one.","fix":"Ask Basis to set up the firm (`python -m basis.admin create-firm`), then accept the owner invitation that appears after sign-in.","retry":"no","signal":null},"BASIS-UPLOAD-001":{"what":"The study already has a document with this sha256.","fix":"Use the existing document.","retry":"no","signal":null},"BASIS-UPLOAD-002":{"what":"No object was uploaded to the signed URL yet (confirm), or the upload was never confirmed (read).","fix":"Upload the bytes to the signed URL, then `POST .../complete`.","retry":"yes","signal":null},"BASIS-UPLOAD-003":{"what":"The stored object's size, content type or sha256 differs from what was registered. The object was deleted.","fix":"Upload the registered file again.","retry":"yes","signal":null},"BASIS-UPLOAD-004":{"what":"The appraisal is not a PDF, a MISMO 3.6 XML or a safe UAD 3.6 ZIP of its declared type. The object was deleted.","fix":"Upload the report PDF, the XML or the delivery ZIP (docs/api/UAD36_INTAKE.md).","retry":"no","signal":null},"BASIS-UPLOAD-005":{"what":"The document has no report PDF to render: a bare XML with no companion, or a package that is not usable.","fix":"Upload the report PDF as another appraisal document.","retry":"no","signal":null},"BASIS-UPLOAD-006":{"what":"No document with that id in the study.","fix":"Check the id.","retry":"no","signal":null},"BASIS-UPLOAD-007":{"what":"The row says uploaded but the object is gone from storage.","fix":"Operator: check the bucket's lifecycle rules; re-upload the file.","retry":"no","signal":null},"BASIS-UPLOAD-008":{"what":"The dev upload route was called on a deployment that uses GCS.","fix":"Upload to the signed GCS URL.","retry":"no","signal":null},"BASIS-UPLOAD-009":{"what":"The upload is larger than the maximum.","fix":"Upload a smaller file.","retry":"no","signal":null},"BASIS-UPLOAD-010":{"what":"The signed token is unknown, expired, or the headers differ from the ticket.","fix":"Request a new upload ticket.","retry":"yes","signal":null},"BASIS-UPLOAD-011":{"what":"A new signed upload URL was asked for a document whose upload is already confirmed; its bytes are immutable (they hash to the registered sha256).","fix":"Nothing to resume for this document. To replace the file, register the new bytes as a new document.","retry":"no","signal":null},"BASIS-UPLOAD-012":{"what":"A browser copy was asked for a document that is not a photo (a PDF, a ZIP, a text file).","fix":"Use `.../content` for the document's bytes, or `.../pdf` for an appraisal.","retry":"no","signal":null},"BASIS-UPLOAD-013":{"what":"A HEIC or HEIF photo's bytes cannot be decoded (damaged, cut short, or over the pixel limit); the analysis flags the same photo as not readable.","fix":"Export the photo again from the phone (or as a JPEG) and upload it as a new document.","retry":"no","signal":null},"BASIS-STUDY-001":{"what":"The study's intake lacks a field the output cannot be produced without (price, acquisition costs, land source and value, use, placed-in-service date, state).","fix":"`PUT /v1/studies/{id}/intake` with the fields named (docs/api/STUDY_RESULT.md), then start again.","retry":"yes","signal":null},"BASIS-STUDY-002":{"what":"No appraisal document has a confirmed upload.","fix":"Upload and confirm the appraisal, then start again.","retry":"yes","signal":null},"BASIS-STUDY-003":{"what":"The study is archived (soft deleted).","fix":"Nothing: archived studies are read-only.","retry":"no","signal":null},"BASIS-STUDY-004":{"what":"A compare-and-set lost: the study is not at the stage and revision the request assumed (another decision landed first, or the decision names an old revision).","fix":"`GET /v1/studies/{id}` and decide on the current stage and revision.","retry":"yes","signal":null},"BASIS-STUDY-005":{"what":"The study is at the review stage but the workflow has not opened the gate: the work it reviews is still running (`processing`) or a stage failed (`failed`).","fix":"Wait for `waiting_review` (poll `GET .../workflow`), or retry the failed stage first.","retry":"yes","signal":null},"BASIS-STUDY-006":{"what":"Temporal has no record of `study-{id}` although the study progressed past its first stage (namespace retention, a different namespace).","fix":"Operator: the execution is gone; the study cannot be resumed automatically. Start a new study, or restore the namespace.","retry":"no","signal":null},"BASIS-STUDY-007":{"what":"The execution has closed (completed, failed, cancelled, terminated, timed out).","fix":"A failed or terminated execution cannot be resumed; its run is kept for investigation (`GET .../workflow`, `GET .../timeline`).","retry":"no","signal":null},"BASIS-STUDY-008":{"what":"No stage has failed, or the study was cancelled: the workflow's `retry` validator refused.","fix":"Nothing to retry; check `GET .../workflow` `failed_stage`.","retry":"no","signal":null},"BASIS-STUDY-009":{"what":"The study has no workflow yet.","fix":"Start the study first.","retry":"yes","signal":null},"BASIS-STUDY-010":{"what":"The revision asked for is above the study's current one.","fix":"Ask for a revision up to `revision` of `GET /v1/studies/{id}`.","retry":"no","signal":null},"BASIS-STUDY-011":{"what":"The revision has no appraisal extraction (only the first revision and appraisal rejections extract).","fix":"Read the extraction of the revision that extracted (the fields of this revision were carried from it).","retry":"no","signal":null},"BASIS-STUDY-012":{"what":"The `Idempotency-Key` was already used for another decision (the review row's second guard).","fix":"Use a fresh key.","retry":"yes","signal":null},"BASIS-STUDY-013":{"what":"A correction's `entity_type` is not one the decided stage accepts.","fix":"Use the types the operation description lists for the stage.","retry":"yes","signal":null},"BASIS-STUDY-014":{"what":"A correction's `entity_id` (or a `photo_room` `after.room_id`) is not in the decided revision of this study.","fix":"Use the ids the output routes return for that revision.","retry":"yes","signal":null},"BASIS-STUDY-015":{"what":"A `component` `count`, a `room_component`, a `photo_room`, a `component_remove` or an `extraction_field_add` value the workflow would refuse (not a whole number from 1, an unknown label, not exactly a `room_id`, a removal with fields, an unknown field key, a value of the wrong type, a page past the appraisal PDF, blank evidence).","fix":"Fix the value.","retry":"yes","signal":null},"BASIS-STUDY-016":{"what":"An approval carried corrections (the workflow would refuse the decision after the API recorded it).","fix":"Reject with the corrections instead.","retry":"yes","signal":null},"BASIS-STUDY-017":{"what":"No study with that id is visible to the caller.","fix":"Check the id and the caller's firm.","retry":"no","signal":null},"BASIS-STUDY-018":{"what":"The `If-Match` entity tag is not the intake's current one (someone saved the intake since the client read it), or `If-Match: *` on a study with no intake.","fix":"Read the intake again (`GET .../intake`), reapply the change, and send the new `ETag` as `If-Match`.","retry":"yes","signal":null},"BASIS-STUDY-019":{"what":"The deployment requires `If-Match` on intake writes (`INTAKE_REQUIRE_IF_MATCH=true`) and the request had none.","fix":"Read the intake (`GET .../intake`) and send its `ETag` as `If-Match`.","retry":"yes","signal":null},"BASIS-STUDY-020":{"what":"A `component_remove` or `extraction_field_add` correction has no reason (or a blank one): removing or adding a row is engineer evidence and must say why.","fix":"Give the reason.","retry":"yes","signal":null},"BASIS-STUDY-021":{"what":"One decision removes the same component twice, removes a component and also corrects it, or adds the same appraisal field twice.","fix":"Send one correction per row (or field).","retry":"yes","signal":null},"BASIS-STUDY-022":{"what":"A `component_remove` names a row the rejection rebuilds anyway: an inventory row of a room with a photo flagged for re-analysis (or a merged room), or a row of a flagged photo; corrections of rebuilt rows are not carried.","fix":"Drop the removal (or the re-analysis) and remove the row from the next revision.","retry":"yes","signal":null},"BASIS-STUDY-023":{"what":"The decision removes every inventory row of a reconciled room: the room would fall back to its per-photo rows and the room step would rebuild the inventory.","fix":"Keep at least one inventory row (correct it), or flag the room's photos for re-analysis.","retry":"yes","signal":null},"BASIS-STUDY-024":{"what":"An `extraction_field_add` names a key the extraction already has.","fix":"Correct the existing field with an `extraction_field` correction.","retry":"yes","signal":null},"BASIS-STUDY-030":{"what":"The study is not `completed`: only a completed study is reopened at a gate or has a revision restored (docs/api/REVISIONS.md).","fix":"Reject at the gate the study waits at; `retry` a failed stage; `restart` a cancelled study.","retry":"no","signal":null},"BASIS-STUDY-031":{"what":"An execution of the study's workflow is running: the completed one is still closing, or a concurrent reopen or restore won the start.","fix":"Wait for `GET .../workflow` to report the execution closed, or for the gate the other request opened.","retry":"yes","signal":null},"BASIS-STUDY-032":{"what":"The revision number is not one of the study's (1 to its current revision).","fix":"Read `GET .../revisions` for the numbers the study has.","retry":"no","signal":null},"BASIS-STUDY-033":{"what":"The revision to restore is the study's current one; restoring it would copy the current state onto itself.","fix":"Reopen the study at a gate instead (`POST .../reopen`).","retry":"no","signal":null},"BASIS-STUDY-034":{"what":"The revision never reached a review gate (the execution was cancelled or restarted during extraction), so there is no reviewed state to restore.","fix":"Restore a revision whose `stage_reached` in `GET .../revisions` is a review gate or later.","retry":"no","signal":null},"BASIS-STUDY-035":{"what":"The study's workflow execution is running (in progress, waiting at a review gate, or holding a failed stage for a retry), or the study was started while the archive was being decided. Archiving it would leave an execution working on a study its activities may no longer move (every transition refuses an archived study), so the archive is refused rather than silently stopping or failing the run.","fix":"Cancel the study first (`POST /v1/studies/{id}/cancel`); once its execution has closed (`GET .../workflow` `execution_status` not `RUNNING`), archive it.","retry":"after fix","signal":null},"BASIS-STUDY-036":{"what":"The study has started: the run read its intake, and the result and the report are priced from it (the cost year, the location factor, the property class, the basis). Replacing it in place would change a result, an export or a signed report after the fact with nothing marking them stale.","fix":"Changing the inputs of a started study is a reopen with new inputs (a new revision), not an edit in place; the intake can be replaced while the study is `uploading`. The reopen and restart that exist keep the intake (docs/api/STUDY_RESULT.md, Open).","retry":"no","signal":null},"BASIS-STUDY-038":{"what":"The study's current revision has been exported (the assets review was approved): its export, report and schedule were computed with the renovation projects as they were, so replacing them in place would leave those out of date (docs/api/RENOVATIONS.md).","fix":"Reopen the study at the assets review (docs/api/REVISIONS.md), change the projects, reprice and approve again.","retry":"no","signal":null},"BASIS-STUDY-039":{"what":"`If-Match` does not name the renovations' current version (someone saved since).","fix":"Read the renovations again, reapply the change, retry with the new tag.","retry":"after fix","signal":null},"BASIS-STUDY-040":{"what":"The document names a file that is not one of the study's uploads, a photograph tagged after a project that is not a photo, or an invoice that is not a document of kind `other`; or a project's dates contradict the intake's (an after-service project placed in service on or before the building, a before-service project started before the acquisition).","fix":"Upload the file first, or correct the document.","retry":"after fix","signal":null},"BASIS-STUDY-037":{"what":"A dollar the study's report would show stands on something missing (EVAL_REPORT 78): an appraisal field (the GLA, the stories, a garage or basement area, the quality rating, the cost-data date), a measured quantity, a count, a cost-table row, a classification, the location or the cost year's index. The rows it holds are written unpriced and the allocation, the report and the signature are withheld.","fix":"The engineer supplies what the blocker names (the appraisal review, the components review, the assets review's measured quantity), or an operator adds the cost-table row; the next revision prices it.","retry":"after fix","signal":null},"BASIS-STUDY-025":{"what":"The `If-Match` entity tag is not the draft's current version (this user's draft on the stage was saved since the client read it, or `If-Match: *` with no draft).","fix":"Read the draft again (`GET .../drafts/{stage}`), merge, and send the new `ETag` as `If-Match` (docs/api/GATE_DRAFTS_AND_RESUME.md).","retry":"yes","signal":null},"BASIS-STUDY-026":{"what":"The draft names a `revision` that is not the study's current one, or the stage has already been decided at that revision: its corrections could never be submitted.","fix":"Reload the gate at the current revision and draft against it; discard the stale draft (`DELETE`) if it is still stored.","retry":"no","signal":null},"BASIS-STUDY-027":{"what":"The caller has no draft on that stage of the study (never saved, already submitted with a decision, or already discarded).","fix":"Nothing to discard; `GET .../drafts/{stage}` lists what exists.","retry":"no","signal":null},"BASIS-STUDY-028":{"what":"The study's execution is still running (or waiting for a retry): there is nothing to restart from.","fix":"Use `POST .../retry` for a failed stage, or `POST .../cancel` first, then restart.","retry":"no","signal":null},"BASIS-STUDY-029":{"what":"The study's execution completed: its outputs and report exist and are not redone.","fix":"Reject a review stage to rework a revision, or create a new study.","retry":"no","signal":null},"BASIS-OBJECT-001":{"what":"The photo's SAM 3 localization is not recorded yet (it runs behind the review).","fix":"Wait for `GET .../objects` to show a `localization`, then add.","retry":"yes","signal":null},"BASIS-OBJECT-002":{"what":"No stored instance of the label is under the point.","fix":"Draw a box around the object instead.","retry":"no","signal":null},"BASIS-OBJECT-003":{"what":"The instance is the model's: evidence of what it found, never deleted.","fix":"Only manual instances can be deleted.","retry":"no","signal":null},"BASIS-OBJECT-004":{"what":"No active instance with that id on this photo at the current revision.","fix":"Read `GET .../objects` for the current ids.","retry":"no","signal":null},"BASIS-OBJECT-005":{"what":"The document is not a photo of the study.","fix":"Check the id.","retry":"no","signal":null},"BASIS-OBJECT-006":{"what":"A decision moved the study to another revision while SAM 3 outlined the box.","fix":"Repeat on the current revision.","retry":"yes","signal":null},"BASIS-OBJECT-007":{"what":"Objects are edited only while the study waits at its edit stage (`components_review`, or `rooms_review` without the components gate).","fix":"Edit at the components review.","retry":"no","signal":null},"BASIS-OBJECT-008":{"what":"The study is at the edit stage but the photos are still being prepared for it (or a stage failed).","fix":"Wait for `waiting_review`.","retry":"yes","signal":null},"BASIS-OBJECT-009":{"what":"SAM 3 could not outline the engineer's box (no localizer, file missing, the call failed or timed out, nothing overlapped). The box was stored without an outline.","fix":"Nothing required; delete the box and draw it again to try another outline.","retry":"yes","signal":null},"BASIS-OBJECT-010":{"what":"The instance is an uncounted candidate (a model instance under its class's count threshold): it is not counted, so there is nothing to exclude (EVAL_REPORT 90).","fix":"Nothing required; to count a candidate, add it (`POST .../objects`, `candidate`).","retry":"no","signal":null},"BASIS-OBJECT-011":{"what":"The instance is an uncounted candidate that was never excluded: restoring counts back only what an engineer excluded (EVAL_REPORT 90).","fix":"To count a candidate, add it (`POST .../objects`, `candidate`).","retry":"no","signal":null},"BASIS-OBJECT-012":{"what":"Marking a photo object Not counted is turned off on this deployment (`OBJECT_EXCLUSION=false`; `GET /v1/capabilities` says `object_exclusion: false`).","fix":"An operator turns the setting on; until then the app does not offer it.","retry":"no","signal":null},"BASIS-WF-001":{"what":"The worker running the activity stopped heartbeating for `heartbeat_timeout` (30 s): the worker died, was killed, or a long step did not heartbeat (EVAL_REPORT 38: `ingest_appraisal` embedding on a cold model).","fix":"Check the worker is alive (Cloud Run logs around the time); retry the stage. If one step always times out, it needs heartbeats (`basis.activities._support.heartbeat`).","retry":"after fix","signal":null},"BASIS-WF-002":{"what":"One attempt ran longer than its `start_to_close_timeout` (`basis.workflow.activity_options`).","fix":"Retry; if a step is always this slow, raise its timeout with a measurement.","retry":"automatic","signal":null},"BASIS-WF-003":{"what":"The activity's attempts together exceeded `schedule_to_close_timeout`: it kept failing or waiting.","fix":"Look at the earlier attempts' `activity.failed` events for the real cause; then `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-WF-004":{"what":"No worker picked the activity up in time (not set by this workflow; listed for completeness).","fix":"Check that a worker polls the task queue.","retry":"after fix","signal":null},"BASIS-WF-005":{"what":"The activity was cancelled: the study was cancelled or the worker drained on shutdown.","fix":"Nothing for a cancelled study; a drained activity is re-run by the next worker.","retry":"automatic","signal":null},"BASIS-WF-006":{"what":"An activity failed with an error type that carries no code of its own (a test fake, a type from before the catalogue).","fix":"Read the message; the type says which class it is.","retry":"after fix","signal":null},"BASIS-WF-007":{"what":"An exception that is not an `ApplicationError` escaped an activity (a database error on an established connection, a bug).","fix":"Read the worker log for the stack trace; fix; `POST /v1/studies/{id}/retry`.","retry":"automatic","signal":null},"BASIS-WF-008":{"what":"The workflow refused a decision: not waiting, wrong stage, stale revision, already decided, unknown decision, a correction type the gate does not take, a bad `entity_id`, an approval with corrections. The API checks the same rules first, so this reaches only the outbox relay (which logs it as final).","fix":"Decide again on the current stage and revision.","retry":"no","signal":null},"BASIS-WF-009":{"what":"No stage has failed, or the study was cancelled.","fix":"Nothing to retry.","retry":"no","signal":null},"BASIS-WF-010":{"what":"The owner cancelled the study (`POST .../cancel`): every activity stopped, the run ended `cancelled`.","fix":"Start a new study.","retry":"no","signal":null},"BASIS-WF-011":{"what":"No decision for `review_deadline_days`; the study is `stalled` and the reminder keeps going.","fix":"Decide; the study resumes.","retry":"yes","signal":null},"BASIS-WF-012":{"what":"The `runs` row of this execution does not exist: `record_run_start` did not run first.","fix":"A workflow ordering defect; report it.","retry":"no","signal":null},"BASIS-WF-013":{"what":"An activity was invoked outside a workflow (no workflow id on the activity).","fix":"Run the activities through the StudyWorkflow.","retry":"no","signal":null},"BASIS-WF-014":{"what":"An input id is missing or not a UUID.","fix":"A contract defect between the workflow and the activity; report it.","retry":"no","signal":null},"BASIS-WF-015":{"what":"The study (or a row it needs) is gone from the database while the workflow runs.","fix":"Operator: the study was deleted outside the API; the execution cannot continue.","retry":"no","signal":null},"BASIS-WF-016":{"what":"The study row is not at the stage the workflow expects and not at the target either (moved by hand, or archived).","fix":"Operator: put the row back at the expected stage, then `POST /v1/studies/{id}/retry`; never edit study rows by hand while a workflow runs.","retry":"after fix","signal":null},"BASIS-WF-017":{"what":"A `SimulateFault` asked for the failure.","fix":"Test only.","retry":"no","signal":null},"BASIS-PROVIDER-001":{"what":"The provider refused the account: out of credit or quota, a missing, invalid or revoked key, no permission (OpenAI `insufficient_quota`, Anthropic `billing_error`, Azure 401/403). Every later call fails the same way, so the stage stops at once and nothing is retried.","fix":"Top up or fix the account or key; then `POST /v1/studies/{id}/retry` (the photos the error stopped run again, the rest is kept).","retry":"after fix","signal":null},"BASIS-PROVIDER-002":{"what":"The provider refused the request as configured: unknown model or deployment, a parameter or value the model does not take, a schema it rejects. The same template fails for every input, so it stops the stage like an account error.","fix":"Fix the model or deployment setting named; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-PROVIDER-003":{"what":"No vision provider is configured at all (dev and test only: the worker refuses to start that way elsewhere).","fix":"Set `OPENAI_API_KEY` or the Azure OpenAI variables.","retry":"no","signal":null},"BASIS-PROVIDER-004":{"what":"No model provider for the room step.","fix":"Configure a provider.","retry":"no","signal":null},"BASIS-PROVIDER-005":{"what":"The provider refused this request's content: an image it cannot process, a request too large, a content-policy block. Another input may work, so only this item fails.","fix":"Replace the file (a photo: re-encode or crop it; the appraisal: a clean PDF); for an extraction `POST /v1/studies/{id}/retry`.","retry":"no","signal":null},"BASIS-PROVIDER-006":{"what":"The call completed but its output cannot be used (invalid JSON for the schema after the retry, a refusal, truncation; Azure DI 4xx). Charged, not retried elsewhere.","fix":"Retry the stage; if it repeats, the prompt or the model setting needs a change.","retry":"after fix","signal":null},"BASIS-PROVIDER-007":{"what":"429, 5xx, 408/409, a timeout or a connection failure after the provider's own retry and the pool's secondary provider.","fix":"Usually transient. If the stage failed, `POST /v1/studies/{id}/retry` once the provider is healthy.","retry":"automatic","signal":null},"BASIS-PROVIDER-008":{"what":"SAM 3 (Replicate or the Cog server) answered 429/5xx or timed out after the localizer's own backoff.","fix":"Nothing: the engineer can still draw boxes; a failed localization never fails the study.","retry":"automatic","signal":null},"BASIS-PROVIDER-009":{"what":"The localizer returned an error a retry cannot fix (a rejected request, a failed prediction, an unreadable result).","fix":"Check the localizer deployment (docs/review_2026-10-15/SAM3_HOSTING.md); boxes can still be drawn by hand.","retry":"no","signal":null},"BASIS-PROVIDER-010":{"what":"Neither `LOCALIZER_URL` nor `REPLICATE_API_TOKEN` is set.","fix":"Configure a localizer for outlines and counts.","retry":"no","signal":null},"BASIS-BUDGET-001":{"what":"The study's remaining budget cannot cover the photo's model call(s).","fix":"Raise `STUDY_BUDGET_USD` (or the photo step's cost) for later studies; this photo stays flagged.","retry":"no","signal":null},"BASIS-BUDGET-002":{"what":"The room step's calls would exceed the remaining budget.","fix":"Raise the budget; the review shows per-photo rows.","retry":"no","signal":null},"BASIS-BUDGET-003":{"what":"The worst case of the residual classifier's calls does not fit the remaining budget (checked before any call).","fix":"Raise the budget and retry, or approve the review as is.","retry":"no","signal":null},"BASIS-BUDGET-004":{"what":"No budget left when the photo reached SAM 3.","fix":"Raise the budget for later studies.","retry":"no","signal":null},"BASIS-BUDGET-005":{"what":"The budget reached zero before the photo's analysis was scheduled; it was not analyzed.","fix":"Raise the budget; the photo has no rows.","retry":"no","signal":null},"BASIS-INGEST-001":{"what":"The study row is gone.","fix":"Operator: the study was deleted outside the API.","retry":"no","signal":null},"BASIS-INGEST-002":{"what":"The appraisal row says uploaded but the object is gone from storage.","fix":"Re-upload the appraisal as a new document; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-INGEST-003":{"what":"The UAD 3.6 ZIP or XML cannot be read (size limits, not a safe ZIP, no XML, bad XML).","fix":"Upload a valid delivery (docs/api/UAD36_INTAKE.md); `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-INGEST-004":{"what":"The companion document chosen as a bare XML's report PDF is not a PDF.","fix":"Upload the real report PDF; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-INGEST-005":{"what":"The report PDF cannot be parsed (corrupt, encrypted, not a PDF).","fix":"Export the appraisal to a clean PDF and upload it; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-INGEST-006":{"what":"An unpublished study corpus version from an earlier attempt could not be discarded.","fix":"Operator: inspect `corpus_versions` for the study; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-EXTRACT-001":{"what":"The document the workflow named is not an appraisal of the study.","fix":"Operator: a workflow contract defect; report it.","retry":"no","signal":null},"BASIS-EXTRACT-002":{"what":"The appraisal's object is gone from storage.","fix":"Re-upload; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-EXTRACT-003":{"what":"A bare XML's report PDF is gone from storage.","fix":"Re-upload the report PDF; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-EXTRACT-004":{"what":"The report PDF of a bare XML is not a PDF.","fix":"Upload the real report PDF; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-EXTRACT-005":{"what":"The report PDF `ingest_appraisal` chose is not a confirmed appraisal of the study any more.","fix":"Operator: check the document rows; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-EXTRACT-006":{"what":"The appraisal cannot be read as a document (not a PDF/XML/ZIP, empty, corrupt).","fix":"Upload a readable appraisal; `POST /v1/studies/{id}/retry`.","retry":"after fix","signal":null},"BASIS-EXTRACT-007":{"what":"A correction of another type than `extraction_field` reached the extraction.","fix":"A workflow defect; the API refuses such a decision first. Report it.","retry":"no","signal":null},"BASIS-EXTRACT-008":{"what":"A corrected field id does not exist in the study.","fix":"Decide again with the ids `GET .../fields` returns.","retry":"no","signal":null},"BASIS-PHOTO-001":{"what":"The document is not a photo of the study.","fix":"Operator: a contract defect; report it.","retry":"no","signal":null},"BASIS-PHOTO-002":{"what":"The photo's object is gone from storage.","fix":"Re-upload the photo (a new document) and flag the old one as re-analyze, or ignore it.","retry":"no","signal":null},"BASIS-PHOTO-003":{"what":"The image cannot be analyzed: empty, not an image, too small, too many pixels.","fix":"Replace the photo with a readable JPEG or PNG.","retry":"no","signal":null},"BASIS-LOCALIZE-001":{"what":"The document is not a photo of the study.","fix":"Operator: a contract defect.","retry":"no","signal":null},"BASIS-LOCALIZE-002":{"what":"The photo's object is gone from storage.","fix":"Re-upload the photo.","retry":"no","signal":null},"BASIS-LOCALIZE-003":{"what":"The photo cannot be prepared for SAM 3.","fix":"Replace the photo.","retry":"no","signal":null},"BASIS-ROOMS-001":{"what":"A photo of the room is gone from storage.","fix":"Re-upload the photo.","retry":"no","signal":null},"BASIS-ROOMS-002":{"what":"A photo of the room cannot be prepared (it was analyzed before, so this is rare).","fix":"Replace the photo.","retry":"no","signal":null},"BASIS-CORRECT-001":{"what":"A correction names a field the entity type does not have (room: name, room_type, floor, merge_into; component: label, material, attachment, count; asset: category, bucket, recovery_period, irs_section; extraction_field: value_text, value_num, value_date).","fix":"Reject again with the field names listed.","retry":"no","signal":null},"BASIS-CORRECT-002":{"what":"A `value_num` or `recovery_period` is not a finite number.","fix":"Reject again with a number.","retry":"no","signal":null},"BASIS-CORRECT-003":{"what":"A `value_date` is not an ISO date.","fix":"Use `YYYY-MM-DD`.","retry":"no","signal":null},"BASIS-CORRECT-004":{"what":"An asset `bucket` is not y5, y7, y15, y27_5, y39 or land.","fix":"Use a known bucket.","retry":"no","signal":null},"BASIS-CORRECT-005":{"what":"A `recovery_period` is not a positive number of years below 1000.","fix":"Use the bucket's years (5, 7, 15, 27.5, 39).","retry":"no","signal":null},"BASIS-CORRECT-006":{"what":"A component `count` is not a whole number from 1.","fix":"Use a whole number from 1.","retry":"no","signal":null},"BASIS-CORRECT-007":{"what":"A `photo_room` correction is not exactly `{\"room_id\": <uuid>}`.","fix":"Send only `room_id`.","retry":"no","signal":null},"BASIS-CORRECT-008":{"what":"A `room_component` is not a taxonomy label with a count (and known material and attachment).","fix":"Use a label from the component taxonomy with `count`.","retry":"no","signal":null},"BASIS-CORRECT-043":{"what":"An asset correction's measured quantity is incomplete or invalid: `quantity`, `quantity_unit` and `quantity_source` go together, the quantity is a positive number, the unit one the cost table prices in (EA, SF, LF, SY), the source says where it was measured (EVAL_REPORT 78).","fix":"Send all three: the measured quantity, its unit and where it was measured.","retry":"no","signal":null},"BASIS-CORRECT-044":{"what":"A unit price override on an `asset` or `component` correction is invalid: `unit_cost` is dollars to the cent above 0 and at most 10,000,000 per takeoff unit (or null to clear an override), `unit_cost_source` (1 to 300 characters) says where the price comes from and goes with a number only, and the correction's `reason` is required (EVAL_REPORT 90). The decision route refuses the same with a 422.","fix":"Send the price, its source and a reason together.","retry":"no","signal":null},"BASIS-CORRECT-047":{"what":"A component age on an `asset` correction is invalid: exactly one of `effective_age` (years from 0, below 200) and `year_installed` (a calendar year), an `economic_life` above the age, an `age_source` from the list, an `age_source_detail` (1 to 300 characters) and the correction's `reason`; or `effective_age: null` alone to clear (EVAL_REPORT 102, docs/api/OVERRIDES.md section 7). The decision route refuses the same with a 422.","fix":"Send the age, the life, the source and a reason together.","retry":"no","signal":null},"BASIS-CORRECT-048":{"what":"A removal on an `asset` correction is invalid: `removed_by_project` (a project key of the study's renovations) with a `disposition_date` (ISO date) and an optional `removed_share` (above 0, at most 1), and the correction's `reason`; or `removed_by_project: null` alone to clear (EVAL_REPORT 102, docs/api/RENOVATIONS.md). The decision route refuses the same, and a key the renovations do not list, with a 422.","fix":"Name a project of the study's renovations, the disposition date and a reason.","retry":"no","signal":null},"BASIS-CORRECT-045":{"what":"A unit price override names a concealed row of the structure model (an asset with no component): its total is a share of the building's replacement cost new, not a unit price, so a unit price cannot set it (EVAL_REPORT 90). The decision route refuses the same with a 422.","fix":"Correct the square-foot model instead (`structure_model` through `POST .../assets/reprice`).","retry":"no","signal":null},"BASIS-CORRECT-046":{"what":"An asset correction's traced `measurement` is invalid (an unknown key, a unit other than SF, SY or LF, a shape that crosses itself, a cutout outside its ring, a scale missing on an image, a quantity out of range, ...), or comes with `quantity`, `quantity_unit` or `quantity_source` (one way to state a quantity). The message names what is wrong and where; the decision route refuses the same with a 422 (EVAL_REPORT 97, docs/api/OVERRIDES.md section 4).","fix":"Fix what the message names, or send a typed quantity instead.","retry":"no","signal":null},"BASIS-CORRECT-009":{"what":"An `irs_section` is not 1245 or 1250.","fix":"Use 1245 or 1250.","retry":"no","signal":null},"BASIS-CORRECT-010":{"what":"A bucket and a recovery period given together disagree (y5 is 5 years).","fix":"Give the bucket's years or leave the period out.","retry":"no","signal":null},"BASIS-CORRECT-011":{"what":"A section given with a bucket does not allow it (1245: 5/7/15; 1250: 15/27.5/39).","fix":"Fix the section or the bucket.","retry":"no","signal":null},"BASIS-CORRECT-012":{"what":"`to_revision` is not `from_revision + 1`.","fix":"A workflow defect; report it.","retry":"no","signal":null},"BASIS-CORRECT-013":{"what":"The rejected stage does not accept a correction type in the batch.","fix":"Reject with the types the stage accepts (the API lists them).","retry":"no","signal":null},"BASIS-CORRECT-014":{"what":"An `extraction_field` target is not in the rejected revision.","fix":"Use the ids of the decided revision.","retry":"no","signal":null},"BASIS-CORRECT-015":{"what":"An `asset` target is not in the rejected revision.","fix":"Use the ids of the decided revision.","retry":"no","signal":null},"BASIS-CORRECT-016":{"what":"A `photo` or `photo_room` target is not a photo document of the study.","fix":"Use a photo document id.","retry":"no","signal":null},"BASIS-CORRECT-017":{"what":"A moved photo has no room in the rejected revision (its analysis failed).","fix":"Flag the photo for re-analysis instead of moving it.","retry":"no","signal":null},"BASIS-CORRECT-018":{"what":"A `photo_room` `room_id` is not a room of the rejected revision.","fix":"Use a room id of that revision.","retry":"no","signal":null},"BASIS-CORRECT-019":{"what":"A `room_component` names a room that is not in the rejected revision.","fix":"Use a room id of that revision.","retry":"no","signal":null},"BASIS-CORRECT-020":{"what":"A `merge_into` correction also carries other fields.","fix":"Send `merge_into` alone.","retry":"no","signal":null},"BASIS-CORRECT-021":{"what":"The `merge_into` target is not a room of the rejected revision.","fix":"Use a room id of that revision.","retry":"no","signal":null},"BASIS-CORRECT-022":{"what":"A room is merged into itself.","fix":"Name another room.","retry":"no","signal":null},"BASIS-CORRECT-023":{"what":"The merges form a loop (a into b, b into a).","fix":"Merge every room into one target.","retry":"no","signal":null},"BASIS-CORRECT-024":{"what":"The study is gone while merges are recorded.","fix":"Operator: the study was deleted.","retry":"no","signal":null},"BASIS-CORRECT-025":{"what":"A `room` or `component` target is not in the rejected revision.","fix":"Use the ids of the decided revision.","retry":"no","signal":null},"BASIS-CORRECT-026":{"what":"`apply_corrections` refused the batch (one of the CORRECT errors above): the revision started without any correction and the gate asks again.","fix":"Decide again with the corrections fixed.","retry":"yes","signal":null},"BASIS-CORRECT-027":{"what":"A `room` correction's `name` or `room_type` is not non-empty text, or its `floor` is neither text, a whole number nor null.","fix":"Send text (`\"Guest Bedroom\"`, `\"bedroom\"`), a floor as `\"2\"`, `2` or null.","retry":"no","signal":null},"BASIS-CORRECT-028":{"what":"A `component_remove` correction carries fields (its `after` must be `{}`).","fix":"Send `after: {}`.","retry":"no","signal":null},"BASIS-CORRECT-029":{"what":"A `component_remove` or `extraction_field_add` correction has no reason.","fix":"Give the reason.","retry":"no","signal":null},"BASIS-CORRECT-030":{"what":"A component is removed twice, or removed and corrected, in one rejection.","fix":"Send one correction per row.","retry":"no","signal":null},"BASIS-CORRECT-031":{"what":"A removed row is one the rejection rebuilds anyway (an inventory row of a room with a flagged photo or a merge, a row of a flagged photo).","fix":"Remove the row from the next revision instead.","retry":"no","signal":null},"BASIS-CORRECT-032":{"what":"The rejection removes every inventory row of a reconciled room.","fix":"Keep one inventory row, or flag the room's photos for re-analysis.","retry":"no","signal":null},"BASIS-CORRECT-033":{"what":"An `extraction_field_add` `after` is not a key, exactly one value, a page from 1 and non-blank evidence of at most 1000 characters (and nothing else).","fix":"Fix the correction's `after`.","retry":"no","signal":null},"BASIS-CORRECT-034":{"what":"An `extraction_field_add` key is not in the URAR field catalogue.","fix":"Use a `<section>.<field>` key of the catalogue (`basis.extraction.field_mappings`).","retry":"no","signal":null},"BASIS-CORRECT-035":{"what":"An added value does not match the field's catalogue type (a date in `value_date`, a number in `value_num`, a whole number for an integer field, Yes/No for a check box).","fix":"Send the value in its type's member.","retry":"no","signal":null},"BASIS-CORRECT-036":{"what":"An `extraction_field_add` names a key the extraction already has.","fix":"Correct the existing field (`extraction_field`).","retry":"no","signal":null},"BASIS-CORRECT-037":{"what":"An added field's page is past the appraisal PDF's page count.","fix":"Give the page the value is printed on.","retry":"no","signal":null},"BASIS-CORRECT-038":{"what":"The same field is added twice to one extraction in one rejection.","fix":"Add each field once.","retry":"no","signal":null},"BASIS-CORRECT-039":{"what":"An `extraction_field_add` target is not an extraction of the rejected revision.","fix":"Use the extraction id of the decided revision.","retry":"no","signal":null},"BASIS-CORRECT-040":{"what":"A `reprice` correction is not exactly `{\"fingerprint\": <64 hex>}`.","fix":"Request the rebuild with `POST /studies/{id}/assets/reprice`, which writes it.","retry":"no","signal":null},"BASIS-CORRECT-041":{"what":"A `structure_model` correction has an unknown member, no member, a class or type outside the RSMeans vocabularies, or a living area outside (0, 100,000] SF.","fix":"Send `model_class` (economy, average, custom, luxury), `building_type` (1 story ... 3 story) and/or `living_area_sf`.","retry":"no","signal":null},"BASIS-CORRECT-042":{"what":"A study-level correction (`reprice`, `structure_model`) names another entity than its own study.","fix":"Its `entity_id` is the study id.","retry":"no","signal":null},"BASIS-ASSETS-001":{"what":"A correction of another type than `asset` reached the assets step.","fix":"A workflow defect; report it.","retry":"no","signal":null},"BASIS-ASSETS-002":{"what":"A corrected asset id is not in the study (or has no component).","fix":"Decide again with the ids `GET .../assets` returns.","retry":"no","signal":null},"BASIS-ASSETS-003":{"what":"The corrected asset's component was not carried into this revision.","fix":"A workflow defect; report it.","retry":"no","signal":null},"BASIS-ASSETS-004":{"what":"An asset correction changes the bucket to one with no standard recovery period (land) without giving `recovery_period`.","fix":"Give `recovery_period` with the bucket.","retry":"no","signal":null},"BASIS-ASSETS-005":{"what":"The rules-table row that classified the component is marked contested (the authorities disagree).","fix":"The engineer confirms or corrects the bucket at the assets review.","retry":"no","signal":"rule_contested:"},"BASIS-ASSETS-006":{"what":"No chat provider is wired for the residual classifier; the component got a fallback classification.","fix":"Configure the classifier provider; the engineer classifies by hand meanwhile.","retry":"no","signal":"classifier_unavailable"},"BASIS-ASSETS-007":{"what":"A citation could not be verified against the reference text, or the model path produced none.","fix":"The engineer checks the authority by hand.","retry":"no","signal":"citation_unverified"},"BASIS-ASSETS-008":{"what":"The model answered without any search result to cite.","fix":"The engineer supplies the authority.","retry":"no","signal":"missing_evidence"},"BASIS-ASSETS-009":{"what":"The model itself asked for review and said why.","fix":"Read the reason.","retry":"no","signal":"model:"},"BASIS-ASSETS-010":{"what":"The quantity is an upper bound (landscaping: the whole unbuilt lot).","fix":"Measure or confirm the quantity.","retry":"no","signal":"takeoff:upper_bound"},"BASIS-ASSETS-021":{"what":"The engineer's traced measurement names no capture date for its image: undated imagery cannot show the property as it was placed in service (EVAL_REPORT 97).","fix":"Confirm the image shows the property as placed in service, or trace on a dated one.","retry":"no","signal":"measure:IMAGE_UNDATED"},"BASIS-ASSETS-022":{"what":"The traced measurement's image was captured more than `MEASURE_IMAGE_AFTER_SERVICE_DAYS` after the placed-in-service date: it may show improvements made after the purchase (EVAL_REPORT 97).","fix":"Check that the traced item existed at the placed-in-service date.","retry":"no","signal":"measure:IMAGE_AFTER_SERVICE"},"BASIS-ASSETS-023":{"what":"A measurement traced on lon/lat imagery names no pixel size, so its expected error is unknown (EVAL_REPORT 97).","fix":"Give the imagery's pixel size, or confirm the quantity another way.","retry":"no","signal":"measure:ERROR_UNKNOWN"},"BASIS-ASSETS-024":{"what":"A traced measurement's expected error (one pixel on every edge, plus the scale's) is above `MEASURE_ERROR_FLAG_PCT` (EVAL_REPORT 97).","fix":"Trace on sharper imagery or a plan, or confirm the quantity another way.","retry":"no","signal":"measure:COARSE"},"BASIS-ASSETS-011":{"what":"The assets step did not run for want of budget (BASIS-BUDGET-003).","fix":"Raise the budget and retry, or approve as is.","retry":"no","signal":null},"BASIS-ASSETS-012":{"what":"The approved assets could not be promoted to the firm's conventions; the study continued to the export (its result does not depend on the conventions).","fix":"Fix the cause (the activity's error code). This study's rulings stay unpromoted; a later approved study with the same components seeds them.","retry":"no","signal":null},"BASIS-ASSETS-013":{"what":"An approved answer for a context key differed from the firm's convention for it, so the convention was replaced (approvals back to 1).","fix":"None if the new ruling is intended; otherwise correct the asset in a later study.","retry":"no","signal":null},"BASIS-ASSETS-014":{"what":"The firm's rulings for the component's label disagree with equal weight at the tier that would have served it (CLASSIFICATION_CONVENTIONS.md section 9.3), so the rules table or the model classified it instead.","fix":"The engineer rules on the asset at the assets review; the approved ruling becomes the exact convention, which wins next time.","retry":"no","signal":"convention_conflict:"},"BASIS-ASSETS-020":{"what":"A reprice found the property class changed since the revision was classified (the intake changed between the request and the rebuild): nothing was carried and every asset was classified again.","fix":"Review the reclassified assets at the assets review.","retry":"no","signal":null},"BASIS-EXPORT-001":{"what":"The study is gone at export time.","fix":"Operator: the study was deleted.","retry":"no","signal":null},"BASIS-CHECK-001":{"what":"The IRS section does not allow the bucket (1245: 5/7/15; 1250: 15/27.5/39).","fix":"Correct the section or the bucket.","retry":"no","signal":"validation:SECTION_BUCKET_MISMATCH"},"BASIS-CHECK-002":{"what":"An asset is in the `land` bucket.","fix":"Land is not depreciable; move the cost out of the schedule.","retry":"no","signal":"validation:LAND_NOT_DEPRECIABLE"},"BASIS-CHECK-003":{"what":"No IRS section recorded.","fix":"Set 1245 or 1250.","retry":"no","signal":"validation:SECTION_MISSING"},"BASIS-CHECK-004":{"what":"The IRS section is neither 1245 nor 1250.","fix":"Set 1245 or 1250.","retry":"no","signal":"validation:SECTION_UNKNOWN"},"BASIS-CHECK-005":{"what":"The recovery period is not the bucket's.","fix":"Correct the period.","retry":"no","signal":"validation:RECOVERY_PERIOD_MISMATCH"},"BASIS-CHECK-006":{"what":"A building bucket does not match the property class (27.5 residential rental, 39 nonresidential).","fix":"Correct the bucket or the intake's `property_use`.","retry":"no","signal":"validation:BUILDING_BUCKET_PROPERTY_CLASS"},"BASIS-CHECK-007":{"what":"A structural-looking label is classified section 1245.","fix":"Confirm it is really personal property.","retry":"no","signal":"validation:STRUCTURAL_AS_PERSONAL"},"BASIS-CHECK-008":{"what":"A personal-property-looking label is in a building bucket.","fix":"Confirm the classification.","retry":"no","signal":"validation:PERSONAL_AS_BUILDING"},"BASIS-CHECK-009":{"what":"A room-context note (mechanical room items are often 1245). Informational: it never flags by itself.","fix":"None.","retry":"no","signal":"ROOM_CONTEXT"},"BASIS-CHECK-010":{"what":"A section 1245 asset measured in square feet is implausibly large.","fix":"Check the takeoff.","retry":"no","signal":"cross:SECTION_1245_SF_LARGE"},"BASIS-CHECK-011":{"what":"The cost row needs a quantity the takeoff could not produce.","fix":"Measure the item.","retry":"no","signal":"cross:COST_NEEDS_QUANTITY"},"BASIS-CHECK-012":{"what":"No cost row prices the component's label.","fix":"Price it by hand, or add the row to the cost table.","retry":"no","signal":"cross:COST_ROW_MISSING"},"BASIS-CHECK-013":{"what":"The unit cost is below the row's plausible range.","fix":"Check the row and the quantity.","retry":"no","signal":"cross:COST_BELOW_RANGE"},"BASIS-CHECK-014":{"what":"The unit cost is above the row's plausible range.","fix":"Check the row and the quantity.","retry":"no","signal":"cross:COST_ABOVE_RANGE"},"BASIS-CHECK-015":{"what":"The total is not quantity times unit cost.","fix":"Report it: a pricing defect.","retry":"no","signal":"cross:COST_TOTAL_MISMATCH"},"BASIS-CHECK-020":{"what":"A critical field is empty.","fix":"Fill it at the appraisal review (an `extraction_field` correction).","retry":"no","signal":"missing:"},"BASIS-CHECK-021":{"what":"A critical field is below the review threshold.","fix":"Confirm or correct the value.","retry":"no","signal":"low_confidence:"},"BASIS-CHECK-022":{"what":"The validator found a critical field missing.","fix":"Fill it.","retry":"no","signal":"missing_critical"},"BASIS-CHECK-023":{"what":"A value does not parse as its type (a number, a date).","fix":"Correct the value.","retry":"no","signal":"type"},"BASIS-CHECK-024":{"what":"A value is implausible (a date out of range).","fix":"Correct the value.","retry":"no","signal":"range"},"BASIS-CHECK-025":{"what":"The basement area exceeds the gross living area.","fix":"Check both fields.","retry":"no","signal":"basement_vs_gla"},"BASIS-CHECK-026":{"what":"The appraised value is far from the contract price.","fix":"Check both fields.","retry":"no","signal":"value_vs_contract"},"BASIS-CHECK-031":{"what":"The living area on the appraisal's sketch and the gross living area box differ by more than the tolerance (`TAKEOFF_SKETCH_GLA_TOLERANCE`, read only with `TAKEOFF_SKETCH=on`). One of them is wrong, and the takeoff does not use the sketch until they agree.","fix":"Correct the gross living area if the sketch is right, or the sketch's living area if the box is.","retry":"no","signal":"gla_vs_sketch"},"BASIS-CHECK-027":{"what":"Two readers (Azure DI, the text layer, the model) disagree on a field.","fix":"Pick the right value.","retry":"no","signal":"sources_disagree"},"BASIS-CHECK-028":{"what":"Azure Document Intelligence refused the PDF; only the text layer was read.","fix":"Check the values; a clean PDF may read better.","retry":"no","signal":"azure_di_rejected"},"BASIS-CHECK-029":{"what":"A UAD 3.6 XML value is not printed where its caption is on the report PDF.","fix":"Check the XML against the PDF.","retry":"no","signal":"xml_pdf_mismatch"},"BASIS-CHECK-030":{"what":"A bare XML with no report PDF: no regions, no study corpus.","fix":"Upload the report PDF as another appraisal document.","retry":"no","signal":"no_report_pdf"},"BASIS-CHECK-040":{"what":"The model could not tell the room or found nothing usable.","fix":"Assign the room and add components by hand.","retry":"no","signal":"ambiguous"},"BASIS-CHECK-041":{"what":"The room identity is below the confidence floor.","fix":"Confirm the room.","retry":"no","signal":"low_room_confidence:"},"BASIS-CHECK-042":{"what":"The model's answer stayed invalid after one retry; the photo got an `ambiguous` analysis.","fix":"Re-analyze the photo (a `photo` correction) or add by hand.","retry":"no","signal":"invalid_model_output"},"BASIS-CHECK-043":{"what":"The second counting model failed; the base counts stand.","fix":"Check the counts.","retry":"no","signal":"count_fusion_fallback:"},"BASIS-CHECK-050":{"what":"The room step dropped objects it could not reconcile.","fix":"Check the room's inventory against its photos.","retry":"no","signal":"dropped_objects:"},"BASIS-CHECK-051":{"what":"A one-photo room's inventory is the per-photo analysis (configured so).","fix":"None unless the counts look wrong.","retry":"no","signal":"single_photo"},"BASIS-CHECK-052":{"what":"The reconciliation model's answer was unusable; the heuristic merge was used.","fix":"Check the inventory.","retry":"no","signal":"invalid_model_output"},"BASIS-CHECK-053":{"what":"The room has more photos than one call can take.","fix":"Split the room or check the inventory.","retry":"no","signal":"too_many_photos"},"BASIS-CHECK-060":{"what":"The classifier hit its tool-call cap without an answer.","fix":"Classify by hand.","retry":"no","signal":"tool_cap_exceeded"},"BASIS-CHECK-061":{"what":"The classifier hit its iteration cap.","fix":"Classify by hand.","retry":"no","signal":"iteration_cap"},"BASIS-CHECK-062":{"what":"The classifier's final answer did not parse.","fix":"Classify by hand.","retry":"no","signal":"invalid_output"},"BASIS-CHECK-063":{"what":"The classifier timed out.","fix":"Classify by hand or retry.","retry":"no","signal":"timeout"},"BASIS-CHECK-064":{"what":"The classifier's reservation ran out mid-component.","fix":"Raise the budget.","retry":"no","signal":"budget_exceeded"},"BASIS-CHECK-065":{"what":"A provider error on the classifier's call (not an account error, which stops the stage).","fix":"Classify by hand or retry.","retry":"no","signal":"provider_error:"},"BASIS-CHECK-066":{"what":"The classifier produced no classification and no reason.","fix":"Classify by hand.","retry":"no","signal":"no_answer"},"BASIS-CHECK-067":{"what":"A room's photographs mix the acquisition and a renovation project (some tagged after a project, some not, or two projects): its room-level rows (the reconciled inventory, an engineer's added rows) cannot follow one tag, so they stay in the acquisition (docs/api/RENOVATIONS.md).","fix":"Move the project's photographs to a room of their own at the rooms review, or tag every photograph of the room alike.","retry":"after fix","signal":"renovation:ROOM_MIXED"},"BASIS-COST-001":{"what":"No cost index is loaded for the study's cost year (the store holds none and no fetcher supplied one); every priced row takes the latest loaded index with the assumption recorded (COST_INDICES.md section 4), and `summary.basis.cost_index` names the value to enter.","fix":"Enter the year's RSMeans Historical Cost Index (`POST /v1/cost-indices`, or `python -m basis.costs.refresh enter`) or run the refresh job, then rerun the assets step.","retry":"no","signal":"cost:YEAR_INDEX_MISSING"},"BASIS-COST-002":{"what":"The cost year's index is not a published RSMeans value but one converted from a public series (the BLS Producer Price Index) with the error band recorded (COST_INDICES.md section 11).","fix":"Enter the year's published RSMeans Historical Cost Index; a manual entry outranks the converted value.","retry":"no","signal":"cost:YEAR_INDEX_CONVERTED"},"BASIS-COST-003":{"what":"The store's latest version of this source, series, year and region already carries the same value and citation; nothing is written twice.","fix":"Nothing to do; to revise a value, send the new value or citation (it becomes the next version).","retry":"no","signal":null},"BASIS-COST-004":{"what":"A configured source was not asked: fetching is off (`COST_INDEX_FETCH`) or the source lacks its credentials (the RSMeans API without a subscription).","fix":"Turn fetching on or configure the source; or enter the value manually.","retry":"no","signal":null},"BASIS-COST-005":{"what":"A fetcher raised or returned no value for a wanted year (network, timeout, an unexpected document); the store is unchanged for that source.","fix":"Retry (the next scheduled run does); the failures name the year and the cause.","retry":"yes","signal":null},"BASIS-COST-006":{"what":"The study's ZIP (intake or appraisal) has a city row in the location table, but under another state than the subject's; the row is not used and the next candidate (the state's mean) prices the study (EVAL_REPORT 86, 89).","fix":"Check the property's ZIP and state on the intake; correct the one that is wrong and rerun the assets step.","retry":"no","signal":"cost:LOCATION_STATE_MISMATCH"},"BASIS-REPORT-001":{"what":"The document given to the report is not a study export (`format` is not `basis-export/2`).","fix":"Pass the export JSON the export step wrote (`rev-<n>.json`).","retry":"no","signal":null},"BASIS-REPORT-002":{"what":"The export's allocation was withheld (`summary.basis.allocation` is null; `summary.basis.missing` names why: the intake, the cost index, repricing, an unreconciled replacement cost): there is nothing to report.","fix":"Resolve what `missing` names (the intake, a reprice, the reconciliation), approve again, export again.","retry":"after fix","signal":null},"BASIS-REPORT-003":{"what":"A report total does not tie to the cent: the items, classes, categories or schedule against the depreciable basis, or price plus capitalized costs less land against it.","fix":"A defect in the allocation or the report: file it with the export JSON.","retry":"no","signal":null},"BASIS-REPORT-004":{"what":"An export asset is on no report line or on two (or an allocated asset is not in the export).","fix":"A defect: file it with the export JSON.","retry":"no","signal":null},"BASIS-REPORT-005":{"what":"The PDF template did not compile (Typst raised).","fix":"A template defect: file it with the export JSON and the template version.","retry":"no","signal":null},"BASIS-REPORT-006":{"what":"No report for the study and revision: nothing exported yet, or the files are missing from storage. (An export that skipped the report answers with the skip's own code, usually BASIS-REPORT-002.)","fix":"Approve the assets review so the export runs; for missing bytes, export again.","retry":"after fix","signal":null},"BASIS-REPORT-007":{"what":"The study's current revision has no report to sign or preview: it was not exported yet, its export skipped the report, or the study is archived.","fix":"Approve the assets review so the export runs (or resolve what the skip names), then preview and sign.","retry":"after fix","signal":null},"BASIS-REPORT-008":{"what":"A final report needs the firm profile and the study's report answers; one or both are not saved.","fix":"An owner saves the firm profile (`PUT /v1/orgs/{id}/profile`), an engineer the answers (`PUT .../report-answers`); preview again and sign.","retry":"after fix","signal":null},"BASIS-REPORT-009":{"what":"The revision's report is already signed; a signature is never replaced.","fix":"None for this revision. Reopening the study makes a new revision, which is signed on its own.","retry":"no","signal":null},"BASIS-REPORT-010":{"what":"The report rendered now differs from the preview the engineer reviewed (`reviewed_sha256`): an input or the export changed since.","fix":"Open the preview again, review it, and sign with its `ETag`.","retry":"yes","signal":null},"BASIS-REPORT-011":{"what":"The `If-Match` entity tag is not the profile's current one, or `If-Match: *` on a firm with no profile.","fix":"Read the profile again, reapply the change, and send the new `ETag` as `If-Match`.","retry":"yes","signal":null},"BASIS-REPORT-012":{"what":"The `If-Match` entity tag is not the answers' current one, or `If-Match: *` on a study with no answers.","fix":"Read the answers again, reapply the change, and send the new `ETag` as `If-Match`.","retry":"yes","signal":null},"BASIS-REPORT-013":{"what":"The firm has no profile yet.","fix":"An owner saves it with `PUT /v1/orgs/{id}/profile`.","retry":"after fix","signal":null},"BASIS-REPORT-014":{"what":"The signer has saved no signer details (their name, credentials and license) and the signing names none, or the deployment requires saved details (`REPORT_SIGNER_DETAILS_REQUIRED`). A report is signed with the signer's own details, never the firm's.","fix":"The signer saves their details once in their account (`PUT /v1/me/signer`), opens the preview again (it now names them) and signs.","retry":"after fix","signal":null},"BASIS-REPORT-015":{"what":"The signing sent an `engineer` whose name, credentials or license differ from the signer's saved details, which are what the report prints.","fix":"Sign with the saved details (send them, or leave `engineer` out), or change the saved details first (`PUT /v1/me/signer`), open the preview again and sign.","retry":"after fix","signal":null},"BASIS-REPORT-016":{"what":"The `If-Match` entity tag is not the signer details' current one, or `If-Match: *` while none are saved.","fix":"Read the details again, reapply the change, and send the new `ETag` as `If-Match`.","retry":"yes","signal":null},"BASIS-INF-001":{"what":"A model the configured pipeline calls has no configured provider, or the embedding model cannot load: the worker refuses to start.","fix":"Configure the provider or the model setting named, redeploy.","retry":"no","signal":null},"BASIS-INF-002":{"what":"The workflow's validator refused a decision the API had recorded (BASIS-WF-008); the refusal is final.","fix":"Decide again on the current stage and revision.","retry":"no","signal":null},"BASIS-INF-003":{"what":"A message failed `RELAY_MAX_ATTEMPTS` deliveries (Temporal unreachable for long).","fix":"Operator: re-arm the row (`python -m basis.admin`) once Temporal is back.","retry":"after fix","signal":null},"BASIS-INF-004":{"what":"The process could not write its `service_heartbeats` row (database unreachable, or migration 0019 not applied). The process keeps running and retries on the next beat.","fix":"Check the database and run `alembic upgrade head`.","retry":"yes","signal":null},"BASIS-RETENTION-001":{"what":"A completed or archived study older than its firm's `retention_days` had its uploaded files, pages, analyses and model payloads deleted from storage; the export, the signed report, every database row and the timeline were kept.","fix":"Nothing: the rule worked. To undo within the bucket's noncurrent-version window, copy the versions back (infra/staging/RUNBOOK.md 2.4).","retry":"no","signal":null},"BASIS-RETENTION-002":{"what":"A document or page row of a purged study named an object that was already gone from storage (deleted by hand, or by a lifecycle rule) before the purge ran.","fix":"Nothing for the purge (its outcome is the same). Check who deleted the object if it should have been there.","retry":"no","signal":null},"BASIS-RETENTION-003":{"what":"Storage refused or failed to delete one of the study's objects (permissions, an outage). The study is not marked purged; nothing is recorded on its timeline.","fix":"Fix the storage access and run the job again: it lists the remaining objects and finishes the study.","retry":"yes","signal":null},"BASIS-ALERT-001":{"what":"A stage failed (`stage.failed`) and an alert for the operator was enqueued in the same transaction: one `alerts` row keyed by the failure, one `notification` outbox row of `type: alert`, which the relay renders and hands to the email sender.","fix":"Read the study's timeline (`event_type=stage.failed`), fix the cause, `POST /v1/studies/{id}/retry`.","retry":"no","signal":null},"BASIS-ALERT-002":{"what":"No heartbeat of a service (worker, relay) is younger than `ALERT_HEARTBEAT_STALE_SECONDS`: the process died, hangs, or cannot reach the database. One alert per stale period (keyed by the last heartbeat seen); a new one only after the service came back and went stale again.","fix":"Check the process (Cloud Run worker pool instances, container logs) and the database; restart it. Nothing to reset: the next stale period raises its own alert.","retry":"no","signal":null},"BASIS-ALERT-003":{"what":"The email sender failed to send an alert: transient (the relay retries with backoff) or final (the recipient was refused; the outbox row is `dead`).","fix":"Fix the sender's configuration or the recipient (`ALERT_EMAIL_TO`) and requeue the dead row (S2_RUNBOOK section 5); the alert itself is still in `alerts`.","retry":"automatic","signal":null},"BASIS-ALERT-004":{"what":"`ALERT_EMAIL_TO` is not set: the rendered alert was written to the relay's log at WARNING and the outbox row marked delivered. Nobody was emailed.","fix":"Set `ALERT_EMAIL_TO` on the relay so alerts reach someone.","retry":"no","signal":null},"BASIS-ALERT-005":{"what":"A block signal (BASIS-CAPTURE-001 to 004) opened the capture breaker: every capture waits until the breaker's time and resumes on its own. One alert per trip, keyed by the trip number and the time it opened; a second signal while it is open raises none.","fix":"Open the incident's evidence (`GET /v1/ops/capture-incidents`) and read what the page said. Nothing to reset: the breaker closes after its wait, which doubles on each consecutive trip. Set `PROPERTY_CAPTURE=false` to stop captures altogether.","retry":"no","signal":null},"BASIS-CLIENT-001":{"what":"The web app reported an error a user hit in the browser (an uncaught exception, a rejected promise, a failed API call, a `console.error`, an explicit report) and the API stored it with everything the client knew: the user, firm, study, screen, the last actions, the stack, the failed request's status, code and request id, the build and the browser (docs/api/CLIENT_ERRORS.md).","fix":"Diagnose from the record: the event's `http.request_id` finds the server log of the failed request, the breadcrumbs say what the user did, the stack says where. Fix the bug; the record stays until the client-error retention purge.","retry":"no","signal":null},"BASIS-CLIENT-002":{"what":"Browser error records older than `CLIENT_ERRORS_RETENTION_DAYS` (180) were deleted: they are operational data about the application, kept long enough to diagnose a bug a firm reports late, not client files, so the firm's retention rule does not apply.","fix":"Nothing; raise `CLIENT_ERRORS_RETENTION_DAYS` on the job if records are needed longer.","retry":"no","signal":null},"BASIS-INF-005":{"what":"The email sender (`EMAIL_PROVIDER`) failed or refused the invitation email: SMTP unreachable, authentication refused, the recipient rejected (docs/api/FIRMS.md).","fix":"Fix the sender configuration or the address; revoke and invite again (a new invitation is a new email). The invitee can still accept in the app meanwhile.","retry":"yes","signal":null},"BASIS-DEMO-001":{"what":"A visitor to the public site asked for a demo (name, work email, company, role, an optional note) and the API stored it and queued one notification email (docs/api/DEMO_REQUESTS.md).","fix":"Follow up with the visitor; the row stays until the demo-request retention purge.","retry":"no","signal":null},"BASIS-DEMO-002":{"what":"The same email asked for a demo again within ten minutes (a double click, a resubmit, a retry after a lost response): the API answered with the first request's id, stored nothing new and queued no second email.","fix":"Nothing. A request after the window is stored and emailed as a new one.","retry":"no","signal":null},"BASIS-DEMO-003":{"what":"The form's hidden `website` field (a spam trap people never see) was filled in: the API answered exactly as for a stored request and stored nothing.","fix":"Nothing for a bot. If a real visitor reports a lost request, their browser filled the hidden field: ask them to send it again.","retry":"no","signal":null},"BASIS-DEMO-004":{"what":"`DEMO_REQUEST_NOTIFY_EMAIL` is not set on the relay: the demo request was stored but nobody was emailed, and the outbox row was marked delivered.","fix":"Set `DEMO_REQUEST_NOTIFY_EMAIL` on the relay; read the requests stored meanwhile in `GET /v1/ops/demo-requests`.","retry":"no","signal":null},"BASIS-DEMO-005":{"what":"The email sender (`EMAIL_PROVIDER`) failed or refused the demo request's notification: SMTP unreachable, authentication refused, the recipient rejected. The visitor's request was answered and stored before; only the email is late.","fix":"Fix the sender configuration or `DEMO_REQUEST_NOTIFY_EMAIL`; the request is in `GET /v1/ops/demo-requests` meanwhile.","retry":"automatic","signal":null},"BASIS-DEMO-006":{"what":"Demo requests older than `DEMO_REQUESTS_RETENTION_DAYS` (365) were deleted: they are a visitor's contact details, kept long enough to follow up and to recognise a returning firm, and no longer.","fix":"Nothing; a firm that became a customer is in the firm records, not here.","retry":"no","signal":null},"BASIS-CAPTURE-001":{"what":"The imagery site answered with its unusual-traffic page (a `/sorry/` address or the page text) instead of the map: it believes the traffic is automated. A block signal: the breaker opens.","fix":"Nothing for the engineer: the capture waits and resumes when the breaker closes. Operator: read the evidence; if it repeats after each wait, lower the caps or turn `PROPERTY_CAPTURE` off.","retry":"automatic","signal":null},"BASIS-CAPTURE-002":{"what":"The page carries a reCAPTCHA challenge. Basis never answers one. A block signal: the breaker opens.","fix":"Nothing for the engineer: the capture waits and resumes when the breaker closes. Operator: read the evidence; if it repeats after each wait, lower the caps or turn `PROPERTY_CAPTURE` off.","retry":"automatic","signal":null},"BASIS-CAPTURE-003":{"what":"The page went to a consent or sign-in wall (`consent.` or `accounts.` host, or the page asks to sign in or accept) instead of the map. A block signal: the breaker opens.","fix":"Nothing for the engineer: the capture waits and resumes when the breaker closes. Operator: read the evidence; if it repeats after each wait, lower the caps or turn `PROPERTY_CAPTURE` off.","retry":"automatic","signal":null},"BASIS-CAPTURE-004":{"what":"HTTP 429 on the main document or on an imagery or data host. A 429 from the site's feedback or survey endpoints is ignored (EVAL_REPORT 98: their quota is shared by every anonymous visitor). A block signal: the breaker opens.","fix":"Nothing for the engineer: the capture waits and resumes when the breaker closes. Operator: read the evidence; if it repeats after each wait, lower the caps or turn `PROPERTY_CAPTURE` off.","retry":"automatic","signal":null},"BASIS-CAPTURE-005":{"what":"The view rendered blank or black (almost one colour) after the wait for imagery: the GPU or WebGL failed, or the imagery did not stream. Not a block signal; the capture fails and the engineer may start it again.","fix":"Run it again; if every view is blank, check the worker's Chromium flags (`CAPTURE_CHROMIUM_ARGS`) and that WebGL is available.","retry":"after fix","signal":null},"BASIS-CAPTURE-006":{"what":"The address search found no place: the page did not move to a place (no `@lat,lon` in its address) within the wait, or it moved to the no-place spot at latitude 0 near longitude 0 (open ocean), where a search that finds nothing leaves the camera.","fix":"The engineer corrects the address or drops the pin on the house (`PUT .../property/pin` with `lat`/`lon`) and starts the capture again.","retry":"after fix","signal":null},"BASIS-CAPTURE-007":{"what":"A page load or the wait for imagery took longer than its limit (`CAPTURE_PAGE_TIMEOUT_S`).","fix":"Run it again; if it repeats, read the evidence: a slow network or a page that changed.","retry":"after fix","signal":null},"BASIS-CAPTURE-008":{"what":"The browser closed or crashed during the capture (a renderer crash, out of memory, a killed process).","fix":"Run it again; if it repeats, check the worker's memory and the browser log.","retry":"after fix","signal":null},"BASIS-CAPTURE-009":{"what":"A capture was due while the breaker is open after a block signal: it waits until the breaker's time (a durable timer in its workflow) and resumes on its own.","fix":"Nothing; it resumes. The engineer sees that pictures are paused and when they resume.","retry":"automatic","signal":null},"BASIS-CAPTURE-010":{"what":"The hourly or daily cap on page loads or camera moves is spent (`CAPTURE_LOADS_PER_HOUR`, `CAPTURE_LOADS_PER_DAY`, `CAPTURE_MOVES_PER_HOUR`): the capture waits until the oldest navigation in the window ages out.","fix":"Nothing; it resumes. Raise a cap only with a measurement behind it.","retry":"automatic","signal":null},"BASIS-CAPTURE-011":{"what":"The capture waited longer than `CAPTURE_MAX_WAIT_HOURS` in all (breaker or caps) and stopped waiting.","fix":"Start the capture again once `GET /v1/ops/health` shows the breaker closed.","retry":"after fix","signal":null},"BASIS-CAPTURE-012":{"what":"Every planned view was taken and stored with its camera, date and pixel size.","fix":"Nothing.","retry":"no","signal":null},"BASIS-CAPTURE-013":{"what":"Property pictures are turned off on this deployment (`PROPERTY_CAPTURE=false`; `GET /v1/capabilities` says `property_capture: false`).","fix":"An operator turns the setting on; until then the app does not offer it.","retry":"no","signal":null},"BASIS-CAPTURE-014":{"what":"A capture of this study is already queued, waiting or running (one at a time per study).","fix":"Wait for it; its status says when it resumes.","retry":"yes","signal":null},"BASIS-CAPTURE-015":{"what":"The study has no property pin: neither an address nor a point to look at.","fix":"`PUT .../property/pin` with the address (or `lat`/`lon`), then start the capture.","retry":"after fix","signal":null},"BASIS-CAPTURE-016":{"what":"`If-Match` names a version of the pin that is no longer current: someone else moved or confirmed it.","fix":"Read the pin again, reapply the change and send the new `ETag`.","retry":"yes","signal":null},"BASIS-CAPTURE-017":{"what":"The capture's workflow could not be started: the workflow service did not answer. The capture row is marked failed with this code so nothing is left queued.","fix":"Retry after `Retry-After`.","retry":"yes","signal":null},"BASIS-CAPTURE-018":{"what":"The historical views could not be taken: the viewer showed no history control, or stepping through its dates read no date. The capture still completes with today's views; nothing else is lost.","fix":"If it repeats on every capture, the viewer's history control changed: read the evidence's page record and adjust `basis.capture.playwright_browser`.","retry":"after fix","signal":null},"BASIS-CAPTURE-019":{"what":"Street-level pictures were asked for (`CAPTURE_STREET_VIEW`) and the page named no panorama near the property. The capture still completes with its other views.","fix":"Nothing to fix where there is no coverage. If it happens where coverage exists, read the evidence's failed responses: the panorama lookup answered an error (EVAL_REPORT 99).","retry":"no","signal":null},"BASIS-CAPTURE-020":{"what":"The street-level panorama was refused or rendered black: its imagery tiles answered HTTP 401/403 or its lookup a server error (5xx), or the frame was black (EVAL_REPORT 99: every headless attempt; 99.1: a headed browser renders it, so street level needs CAPTURE_HEADLESS=false). Not a block signal, no retry; the capture still completes with its other views.","fix":"Leave `CAPTURE_STREET_VIEW` off until a headless approach is shown to render (EVAL_REPORT 99).","retry":"no","signal":null},"BASIS-CAPTURE-021":{"what":"A view's imagery date could not be read from the viewer's status bar (no text reader installed, the reader failed, or no date in what it read). The view is stored with `imagery_date` null and the reason in `imagery_date_note`; a measurement on it is then undated.","fix":"Install tesseract on the capture worker or set `CAPTURE_TESSERACT`; if it is installed, read the stored status strip (`<label>.status.png`) beside the view.","retry":"after fix","signal":null},"BASIS-GEO-001":{"what":"Public geographic sources are turned off on this deployment (`PUBLIC_GEO=false`, the default).","fix":"An operator turns `PUBLIC_GEO` on and runs the geo worker.","retry":"after fix","signal":null},"BASIS-GEO-002":{"what":"The study's pin has no point yet (no pin, or an address the capture has not placed): the public sources are looked up by point.","fix":"Drop the pin on the house (`PUT .../property/pin` with `lat`/`lon`) or let the capture place it, then ask again.","retry":"after fix","signal":null},"BASIS-GEO-003":{"what":"A gather of the public sources for this study is already queued or running (one at a time per study).","fix":"Wait for it; poll `GET .../property/public`.","retry":"yes","signal":null},"BASIS-GEO-004":{"what":"The gather's workflow could not be started: the workflow service did not answer. The gather row is marked failed with this code so nothing is left queued.","fix":"Retry after `Retry-After`.","retry":"yes","signal":null},"BASIS-GEO-005":{"what":"A public source answered an HTTP error (after the retries for 429 and 5xx) or the connection failed.","fix":"Nothing for the engineer: the other sources go on. Operators read the incident; a source failing for days is marked unavailable in `basis/geo/sources.json`.","retry":"automatic","signal":null},"BASIS-GEO-006":{"what":"A public source did not answer within `GEO_REQUEST_TIMEOUT_S`, after the retries.","fix":"As for `BASIS-GEO-005`.","retry":"automatic","signal":null},"BASIS-GEO-007":{"what":"A public source answered 200 with something unusable: an error document instead of an image, an image that does not decode, JSON that is not a feature collection.","fix":"As for `BASIS-GEO-005`.","retry":"automatic","signal":null},"BASIS-GEO-008":{"what":"No registry source with imagery covers the point, or every one that should answered a blank image there.","fix":"Nothing: the property pictures (if on) or an uploaded site plan are the fallback.","retry":"no","signal":null},"BASIS-GEO-009":{"what":"The state's parcel layer returned no parcel under the point, or the registry has no open parcel layer for the state.","fix":"Check the pin is on the lot; otherwise nothing.","retry":"no","signal":null},"BASIS-GEO-010":{"what":"No federal 3DEP point cloud project covers the point.","fix":"Nothing.","retry":"no","signal":null},"BASIS-GEO-011":{"what":"A lidar point tile or the project's metadata could not be read (not LAZ, a schema without classification, a truncated download).","fix":"As for `BASIS-GEO-005`.","retry":"automatic","signal":null},"BASIS-GEO-012":{"what":"The parcel's area under the pin and the appraisal's site area (`site.area_sqft`) differ by more than `GEO_SITE_TOLERANCE_PCT` (and no set of the owner's adjacent parcels matches).","fix":"The engineer checks the appraisal's site area and the lot: a lot of several parcels, a wrong pin, or a misread area.","retry":"no","signal":"geo:SITE_AREA_MISMATCH"},"BASIS-GEO-013":{"what":"The parcel under the pin alone does not match the appraisal's site area, but it and the owner's adjacent parcels together do (within `GEO_SITE_TOLERANCE_PCT`).","fix":"The engineer confirms the site is the listed parcels.","retry":"no","signal":"geo:SITE_AREA_ADJACENT"},"BASIS-GEO-014":{"what":"The gather ran every source the registry has for the point; each source's outcome is in `sources`.","fix":"Nothing.","retry":"no","signal":null},"BASIS-GEO-015":{"what":"The gather step itself failed after its retries (a timeout, a dead worker, an error it did not classify).","fix":"Ask again (`POST .../property/public`).","retry":"yes","signal":null},"BASIS-GEO-016":{"what":"The lidar covers the point but has no building-classified points (class 6) near the pin, so no heights or footprint are read; the project and its density are still reported.","fix":"Nothing; the project may not classify buildings.","retry":"no","signal":null},"BASIS-GEO-017":{"what":"The building under the pin comes within 1 m of the edge of the area read, so its footprint may be cut there or be a block of attached roofs running to it, and its heights may be a neighbour's (EVAL_REPORT 101.5). Cautious: a building that just fits is flagged too; attached roofs merged well inside the area are not.","fix":"Measure the building another way (the sketch or a traced outline); do not take this footprint as the building's.","retry":"no","signal":null},"BASIS-SITE-001":{"what":"The view carries no pixel size, so it is not a top-down view and nothing on it can be measured.","fix":"Draft on a straight-down capture or a public ortho.","retry":"no","signal":null},"BASIS-SITE-002":{"what":"The view's pixel is coarser than the drafter's limit (`SITE_DRAFT_MAX_PIXEL_M`, 0.16 m by default): on the 0.6 m federal view the drafts were off by a median 30 % and the one-pixel bound alone is 41 % (EVAL_REPORT 106.3).","fix":"Draft on a sharper view (a state or county ortho, or the straight-down capture), or trace by hand.","retry":"no","signal":null},"BASIS-SITE-003":{"what":"SAM 3 returned no instance at the prompt: none overlapping the box at box IoU 0.5 or more, none under the point, or an instance without a mask.","fix":"Move the box or point onto the item, or trace it by hand.","retry":"no","signal":null},"BASIS-SITE-004":{"what":"The outline reaches the edge of the picture, so the item runs out of it and its area would be short.","fix":"Draft on a view that holds the whole item, or trace it by hand.","retry":"no","signal":null},"BASIS-SITE-005":{"what":"The outline covers less ground than the drafter's floor (`MIN_AREA_M2`, 3 m2, a small stoop): too small to outline from above.","fix":"Type the quantity or trace it by hand.","retry":"no","signal":null},"BASIS-SITE-006":{"what":"The outline is not a shape `basis.domain.traced.measure` accepts (the reasons are in the refusal).","fix":"Trace it by hand.","retry":"no","signal":null},"BASIS-SITE-007":{"what":"The call to SAM 3 (Replicate or the self-hosted Cog server) failed after the localizer's own retries.","fix":"Try again later, or trace by hand.","retry":"no","signal":null},"BASIS-SITE-008":{"what":"The family is not drafted from above: a fence (1 to 3 pixels wide, often under trees; EVAL_REPORT 106 found no line method that holds).","fix":"Trace the fence on the picture or from the lot line.","retry":"no","signal":null},"BASIS-GEO-018":{"what":"No building was found under the pin or within 15 m of it: neither the project's building class (6) nor the roof points classified from the heights and planarity (EVAL_REPORT 105), or what was found covers under 20 m2. No shell quantity is drafted.","fix":"Check the pin is on the building; measure the shell another way (the sketch or a traced outline).","retry":"no","signal":null},"BASIS-GEO-019":{"what":"The lidar project has no ground-classified points (class 2) around the building, so no height above ground can be read and the roof points cannot be classified (EVAL_REPORT 105).","fix":"Measure the heights another way (the elevations, the photos).","retry":"no","signal":null},"BASIS-GEO-020":{"what":"The roof outline does not survive being moved inward by the eave overhang (it is too narrow for it), so no wall footprint, perimeter or wall face is drafted; the heights and the roof are (EVAL_REPORT 105).","fix":"Measure the walls another way (the sketch or a traced outline).","retry":"no","signal":null},"BASIS-GEO-021":{"what":"No roof plane of at least 12 points was found on the building's points, so the roof surface, pitch and gutter are not drafted; the walls and heights are (EVAL_REPORT 105).","fix":"Measure the roof another way (the elevations, a traced outline with a typed pitch).","retry":"no","signal":null},"BASIS-GEO-022":{"what":"Trees stand over more than a quarter of the roof (pulses that came back several times, their first return over 0.5 m above the roof), so the roof's points cannot be told from the trees' and no shell quantity is drafted (EVAL_REPORT 105).","fix":"Measure the shell another way (the sketch, the elevations, a traced outline on a leaf-off view).","retry":"no","signal":null},"BASIS-GEO-023":{"what":"The wall's four corners on the photo are not a convex quadrilateral, or the wall is narrower than 120 px in the photo, so nothing is measured (EVAL_REPORT 109).","fix":"Draw the wall's corners again, or use a closer photo of that side.","retry":"no","signal":null},"BASIS-GEO-024":{"what":"The photo's field of view is not known and the wall's corners cannot give it (a vanishing point at infinity, or a field of view outside 15 to 130 degrees), so the wall's height cannot be told from its width (EVAL_REPORT 109).","fix":"Give the photo's field of view (its EXIF focal length), or use a photo that shows the wall's horizontal and vertical edges converging.","retry":"no","signal":null},"BASIS-GEO-025":{"what":"The wall is seen more than 70 degrees off square, or its corners are more than 12 degrees from a rectangle under the photo's camera (a corner misplaced, a wrong field of view, or not one plane), so nothing is measured (EVAL_REPORT 109).","fix":"Use a photo taken more squarely to the wall, or check the corners and the field of view.","retry":"no","signal":null},"BASIS-GEO-026":{"what":"More than half of the wall is hidden (trees, a porch, a car), so its openings are not counted; the wall's height and gross face are (EVAL_REPORT 109).","fix":"Use another photo of that side, or count the openings by hand.","retry":"no","signal":null},"BASIS-MEASURE-001":{"what":"The row is priced on a measurement Basis drafted (the lidar shell's walls, roof or gutters with `MEASURE_DRAFTS_EXTERIOR`, a room's photos with `MEASURE_DRAFTS_INTERIOR`) that the engineer has not verified (EVAL_REPORT 110). While its exposure (its expected error times its price) is above `MEASURE_DRAFT_VERIFY_USD`, the result's `blockers` carry `measure:draft_unverified` and no report is rendered or signed.","fix":"Verify or edit this measurement in the measure tool (or enter the measured quantity) at the assets review.","retry":"no","signal":"measure:DRAFT_UNVERIFIED"},"BASIS-MEASURE-002":{"what":"A room's photos could not be measured: the provider refused them, or no usable answer came back after one retry. The room's rows keep today's formulas (a failed call never becomes a number, EVAL_REPORT 78).","fix":"Nothing to do: measure the room's quantities by hand if they matter.","retry":"no","signal":null},"BASIS-MEASURE-003":{"what":"The room measurements step failed (a provider error after its retries, an account or configuration error, the budget), so no room is drafted and the assets are built on today's formulas (patch `measure-drafts-v1`, EVAL_REPORT 110).","fix":"Fix the cause; the next reopen of the study measures the rooms again.","retry":"no","signal":null},"BASIS-MEASURE-004":{"what":"`MEASURE_DRAFTS_EXTERIOR` is on but a shell quantity was not drafted: no gather stored a shell (`GEO_SHELL`), the pin is not confirmed or moved since, or the shell refused that part (EVAL_REPORT 110). The row keeps today's formula.","fix":"Confirm the pin and gather the public records again with `GEO_SHELL` on, or measure the quantity in the measure tool.","retry":"no","signal":null},"BASIS-MEASURE-005":{"what":"The room measurement calls would exceed the study's remaining budget.","fix":"Raise the budget; the next reopen measures the rooms.","retry":"no","signal":null}};if(typeof module==="object"&&module.exports)module.exports=catalogue;else s.BasisErrorCatalogue=catalogue;})(globalThis);
